/* 학생수업일정 목록조회 */ SELECT * FROM ( /* 1. 강의 일정 */ SELECT L.LCTR_ID AS SCHDL_ID, '강의' AS SCHDL_TYNM, L.LCTRNM AS NM, L.LCTR_SDTTM AS SDTTM, L.LCTR_EDTTM AS EDTTM, L.LCTRNM AS EXPLN FROM TB_LMS_LCTR_WKNO_SCHDL LWS JOIN TB_LMS_LCTR L ON LWS.LCTR_WKNO_SCHDL_ID = L.LCTR_WKNO_SCHDL_ID WHERE LWS.SBJCT_ID = #{sbjctId}
AND L.LCTRNM LIKE '%' || #{searchValue} || '%'
UNION ALL /* 2. 학사 일정 */ SELECT ACAD.ACAD_SCHDL_ID SCHDL_ID, '학사일정' AS SCHDL_TYNM, ACAD.ACAD_SCHDL_EXPLN AS NM, ACAD.ACAD_SCHDL_SDTTM AS SDTTM, ACAD.ACAD_SCHDL_EDTTM AS EDTTM, ACAD.ACAD_SCHDL_EXPLN AS EXPLN FROM TB_LMS_SBJCT S JOIN TB_LMS_SMSTR_CHRT CHRT ON S.SMSTR_CHRT_ID = CHRT.SMSTR_CHRT_ID AND CHRT.ORG_ID = 'LMSBASIC' JOIN TB_LMS_ACAD_SCHDL ACAD ON ACAD.SMSTR_CHRT_ID = CHRT.SMSTR_CHRT_ID AND ACAD.ORG_ID = CHRT.ORG_ID WHERE S.SBJCT_ID = #{sbjctId}
AND ACAD.ACAD_SCHDL_EXPLN LIKE '%' || #{searchValue} || '%'
UNION ALL /* 3. 과제 일정 */ SELECT ASMT.ASMT_ID SCHDL_ID, '과제' AS SCHDL_TYNM, ASMT.ASMT_TTL AS NM, ASMT.ASMT_SBMSN_SDTTM AS SDTTM, ASMT.ASMT_SBMSN_EDTTM AS EDTTM, ASMT.ASMT_CTS AS EXPLN FROM TB_LMS_SBJCT S JOIN TB_LMS_ASMT ASMT ON S.SBJCT_ID = ASMT.SBJCT_ID WHERE S.SBJCT_ID = #{sbjctId}
AND ASMT.ASMT_TTL LIKE '%' || #{searchValue} || '%'
UNION ALL /* 4. 토론 일정 */ SELECT DSCS.DSCS_ID SCHDL_ID, '토론' AS SCHDL_TYNM, DSCS.DSCS_TTL AS NM, DSCS.DSCS_SDTTM AS SDTTM, DSCS.DSCS_EDTTM AS EDTTM, DSCS.DSCS_CTS AS EXPLN FROM TB_LMS_SBJCT S JOIN TB_LMS_DSCS DSCS ON S.SBJCT_ID = DSCS.SBJCT_ID WHERE S.SBJCT_ID = #{sbjctId}
AND DSCS.DSCS_TTL LIKE '%' || #{searchValue} || '%'
UNION ALL /* 5. 세미나 일정 */ SELECT SMNR.SMNR_ID SCHDL_ID, '세미나' AS SCHDL_TYNM, SMNR.SMNRNM AS NM, SMNR.SMNR_SDTTM AS SDTTM, SMNR.SMNR_EDTTM AS EDTTM, DBMS_LOB.SUBSTR(SMNR.SMNR_CTS, 4000, 1) AS EXPLN FROM TB_LMS_SBJCT S JOIN TB_LMS_SMNR SMNR ON S.SBJCT_ID = SMNR.SBJCT_ID WHERE S.SBJCT_ID = #{sbjctId}
AND SMNR.SMNRNM LIKE '%' || #{searchValue} || '%'
UNION ALL /* 6. 설문 일정 */ SELECT SRVY.SRVY_ID SCHDL_ID, '설문' AS SCHDL_TYNM, SRVY.SRVY_TTL AS NM, SRVY.SRVY_SDTTM AS SDTTM, SRVY.SRVY_EDTTM AS EDTTM, SRVY.SRVY_CTS AS EXPLN FROM TB_LMS_SBJCT S JOIN TB_LMS_SRVY SRVY ON S.SBJCT_ID = SRVY.SBJCT_ID AND SRVY.UP_SRVY_ID IS NULL WHERE S.SBJCT_ID = #{sbjctId}
AND SRVY.SRVY_TTL LIKE '%' || #{searchValue} || '%'
UNION ALL /* 7. 시험 / 퀴즈 일정 */ SELECT EXAM.EXAM_BSC_ID SCHDL_ID, CASE WHEN EXAM.EXAM_TYCD = 'EXAM' THEN '시험' ELSE '퀴즈' END AS SCHDL_TYNM, EXAM.EXAM_TTL AS NM, (SELECT MIN(EXAM_PSBL_SDTTM) FROM TB_LMS_EXAM_DTL WHERE EXAM_BSC_ID = EXAM.EXAM_BSC_ID) AS SDTTM, (SELECT MIN(EXAM_PSBL_EDTTM) FROM TB_LMS_EXAM_DTL WHERE EXAM_BSC_ID = EXAM.EXAM_BSC_ID) AS EDTTM, EXAM.EXAM_CTS AS EXPLN FROM TB_LMS_SBJCT S JOIN TB_LMS_EXAM_BSC EXAM ON S.SBJCT_ID = EXAM.SBJCT_ID AND EXAM.EXAM_TYCD IN ('EXAM', 'QUIZ') WHERE S.SBJCT_ID = #{sbjctId}
AND EXAM.EXAM_TTL LIKE '%' || #{searchValue} || '%'
AND EXISTS ( SELECT 1 FROM TB_LMS_EXAM_DTL WHERE EXAM_BSC_ID = EXAM.EXAM_BSC_ID AND EXAM_PSBL_SDTTM IS NOT NULL AND EXAM_PSBL_EDTTM IS NOT NULL ) ) A /* 모든 일정을 시작일시 기준으로 순차 정렬 */ ORDER BY A.SDTTM ASC

/* 교순수업일정 목록조회 */ SELECT * FROM ( /* 1. 강의 일정 */ SELECT L.LCTR_ID AS SCHDL_ID, '강의' AS SCHDL_TYNM, L.LCTRNM AS NM, L.LCTR_SDTTM AS SDTTM, L.LCTR_EDTTM AS EDTTM, L.LCTRNM AS EXPLN FROM TB_LMS_LCTR_WKNO_SCHDL LWS JOIN TB_LMS_LCTR L ON LWS.LCTR_WKNO_SCHDL_ID = L.LCTR_WKNO_SCHDL_ID WHERE LWS.SBJCT_ID = #{sbjctId}
AND L.LCTRNM LIKE '%' || #{searchValue} || '%'
UNION ALL /* 2. 학사 일정 */ SELECT ACAD.ACAD_SCHDL_ID SCHDL_ID, '학사일정' AS SCHDL_TYNM, ACAD.ACAD_SCHDL_EXPLN AS NM, ACAD.ACAD_SCHDL_SDTTM AS SDTTM, ACAD.ACAD_SCHDL_EDTTM AS EDTTM, ACAD.ACAD_SCHDL_EXPLN AS EXPLN FROM TB_LMS_SBJCT S JOIN TB_LMS_SMSTR_CHRT CHRT ON S.SMSTR_CHRT_ID = CHRT.SMSTR_CHRT_ID AND CHRT.ORG_ID = 'LMSBASIC' JOIN TB_LMS_ACAD_SCHDL ACAD ON ACAD.SMSTR_CHRT_ID = CHRT.SMSTR_CHRT_ID AND ACAD.ORG_ID = CHRT.ORG_ID WHERE S.SBJCT_ID = #{sbjctId}
AND ACAD.ACAD_SCHDL_EXPLN LIKE '%' || #{searchValue} || '%'
UNION ALL /* 2-1. 교수개인수업일정 */ SELECT CLAS.CLAS_SCHDL_ID SCHDL_ID, '일정' AS SCHDL_TYNM, CLAS.CLAS_SCHDL_TTL AS NM, CLAS.CLAS_SCHDL_SDTTM AS SDTTM, CLAS.CLAS_SCHDL_EDTTM AS EDTTM, CLAS.CLAS_SCHDL_EXPLN AS EXPLN FROM TB_LMS_SBJCT S JOIN TB_LMS_SMSTR_CHRT CHRT ON S.SMSTR_CHRT_ID = CHRT.SMSTR_CHRT_ID JOIN TB_LMS_CLAS_SCHDL CLAS ON CLAS.SMSTR_CHRT_ID = CHRT.SMSTR_CHRT_ID AND CLAS.SBJCT_ID = S.SBJCT_ID WHERE S.SBJCT_ID = #{sbjctId}
AND CLAS.CLAS_SCHDL_TTL LIKE '%' || #{searchValue} || '%'
UNION ALL /* 3. 과제 일정 */ SELECT ASMT.ASMT_ID SCHDL_ID, '과제' AS SCHDL_TYNM, ASMT.ASMT_TTL AS NM, ASMT.ASMT_SBMSN_SDTTM AS SDTTM, ASMT.ASMT_SBMSN_EDTTM AS EDTTM, ASMT.ASMT_CTS AS EXPLN FROM TB_LMS_SBJCT S JOIN TB_LMS_ASMT ASMT ON S.SBJCT_ID = ASMT.SBJCT_ID WHERE S.SBJCT_ID = #{sbjctId}
AND ASMT.ASMT_TTL LIKE '%' || #{searchValue} || '%'
UNION ALL /* 4. 토론 일정 */ SELECT DSCS.DSCS_ID SCHDL_ID, '토론' AS SCHDL_TYNM, DSCS.DSCS_TTL AS NM, DSCS.DSCS_SDTTM AS SDTTM, DSCS.DSCS_EDTTM AS EDTTM, DSCS.DSCS_CTS AS EXPLN FROM TB_LMS_SBJCT S JOIN TB_LMS_DSCS DSCS ON S.SBJCT_ID = DSCS.SBJCT_ID WHERE S.SBJCT_ID = #{sbjctId}
AND DSCS.DSCS_TTL LIKE '%' || #{searchValue} || '%'
UNION ALL /* 5. 세미나 일정 */ SELECT SMNR.SMNR_ID SCHDL_ID, '세미나' AS SCHDL_TYNM, SMNR.SMNRNM AS NM, SMNR.SMNR_SDTTM AS SDTTM, SMNR.SMNR_EDTTM AS EDTTM, DBMS_LOB.SUBSTR(SMNR.SMNR_CTS, 4000, 1) AS EXPLN FROM TB_LMS_SBJCT S JOIN TB_LMS_SMNR SMNR ON S.SBJCT_ID = SMNR.SBJCT_ID WHERE S.SBJCT_ID = #{sbjctId}
AND SMNR.SMNRNM LIKE '%' || #{searchValue} || '%'
UNION ALL /* 6. 설문 일정 */ SELECT SRVY.SRVY_ID SCHDL_ID, '설문' AS SCHDL_TYNM, SRVY.SRVY_TTL AS NM, SRVY.SRVY_SDTTM AS SDTTM, SRVY.SRVY_EDTTM AS EDTTM, SRVY.SRVY_CTS AS EXPLN FROM TB_LMS_SBJCT S JOIN TB_LMS_SRVY SRVY ON S.SBJCT_ID = SRVY.SBJCT_ID AND SRVY.UP_SRVY_ID IS NULL WHERE S.SBJCT_ID = #{sbjctId}
AND SRVY.SRVY_TTL LIKE '%' || #{searchValue} || '%'
UNION ALL /* 7. 시험 / 퀴즈 일정 */ SELECT EXAM.EXAM_BSC_ID SCHDL_ID, CASE WHEN EXAM.EXAM_TYCD = 'EXAM' THEN '시험' ELSE '퀴즈' END AS SCHDL_TYNM, EXAM.EXAM_TTL AS NM, (SELECT MIN(EXAM_PSBL_SDTTM) FROM TB_LMS_EXAM_DTL WHERE EXAM_BSC_ID = EXAM.EXAM_BSC_ID) AS SDTTM, (SELECT MIN(EXAM_PSBL_EDTTM) FROM TB_LMS_EXAM_DTL WHERE EXAM_BSC_ID = EXAM.EXAM_BSC_ID) AS EDTTM, EXAM.EXAM_CTS AS EXPLN FROM TB_LMS_SBJCT S JOIN TB_LMS_EXAM_BSC EXAM ON S.SBJCT_ID = EXAM.SBJCT_ID AND EXAM.EXAM_TYCD IN ('EXAM', 'QUIZ') WHERE S.SBJCT_ID = #{sbjctId}
AND EXAM.EXAM_TTL LIKE '%' || #{searchValue} || '%'
AND EXISTS ( SELECT 1 FROM TB_LMS_EXAM_DTL WHERE EXAM_BSC_ID = EXAM.EXAM_BSC_ID AND EXAM_PSBL_SDTTM IS NOT NULL AND EXAM_PSBL_EDTTM IS NOT NULL ) ) A /* 모든 일정을 시작일시 기준으로 순차 정렬 */ ORDER BY A.SDTTM ASC

mapper.update:
UPDATE TB_LMS_CLAS_SCHDL
   SET CLAS_SCHDL_TTL   = #{clasSchdlTtl}
     , CLAS_SCHDL_SDTTM = #{clasSchdlSdttm}
     , CLAS_SCHDL_EDTTM = #{clasSchdlEdttm}
     , CLAS_SCHDL_EXPLN = #{clasSchdlExpln}
     , MDFR_ID          = #{mdfrId}
     , MOD_DTTM         = TO_CHAR(SYSDATE, 'YYYYMMDDHH24MISS')
 WHERE CLAS_SCHDL_ID    = #{clasSchdlId}

mapper.select:
/* SQL ID : calendarDAO.listCalendar 설 명 : 캘린더 정보 조회 */ WITH COLORS AS ( SELECT 1 AS ROWNUM , '#D0DBF2' AS BG_COLOR UNION ALL SELECT 2 AS ROWNUM , '#D4BFF5' AS BG_COLOR UNION ALL SELECT 3 AS ROWNUM , '#FAC5D4' AS BG_COLOR UNION ALL SELECT 4 AS ROWNUM , '#CEF5EE' AS BG_COLOR UNION ALL SELECT 5 AS ROWNUM , '#F0F7C8' AS BG_COLOR UNION ALL SELECT 6 AS ROWNUM , '#B3E0E8' AS BG_COLOR UNION ALL SELECT 7 AS ROWNUM , '#F5DDB0' AS BG_COLOR UNION ALL SELECT 8 AS ROWNUM , '#C9ADAD' AS BG_COLOR UNION ALL SELECT 9 AS ROWNUM , '#D2D9C1' AS BG_COLOR UNION ALL SELECT 10 AS ROWNUM , '#E0DECC' AS BG_COLOR UNION ALL SELECT 11 AS ROWNUM , '#F2EAA2' AS BG_COLOR UNION ALL SELECT 12 AS ROWNUM , '#BAE2F7' AS BG_COLOR UNION ALL SELECT 13 AS ROWNUM , '#B8B59A' AS BG_COLOR UNION ALL SELECT 14 AS ROWNUM , '#C1D9BF' AS BG_COLOR UNION ALL SELECT 15 AS ROWNUM , '#D9D3A5' AS BG_COLOR UNION ALL SELECT 16 AS ROWNUM , '#C7EDED' AS BG_COLOR UNION ALL SELECT 17 AS ROWNUM , '#B2D9B0' AS BG_COLOR UNION ALL SELECT 18 AS ROWNUM , '#D2D6B8' AS BG_COLOR UNION ALL SELECT 19 AS ROWNUM , '#FFCBCB' AS BG_COLOR UNION ALL SELECT 20 AS ROWNUM , '#E0C5D4' AS BG_COLOR ) , CALENDAR_INFO AS ( SELECT ROW_NUMBER() OVER(ORDER BY ODR, NAME) AS ROWNUM , CALENDAR_ID , NAME , DVCLAS_NO FROM VW_CALENDAR_INFO WHERE ( USER_TYPES = 'ALL'
USER_TYPES LIKE '%' || #{item} || '%'
) AND ( USER_ID = #{userId} OR CALENDAR_ID IN ('course', 'personal') ) ) SELECT A.CALENDAR_ID , A.NAME , NVL(B.BG_COLOR, '#' || HEX(FLOOR(16 + RAND() * (255 - 16))) || HEX(FLOOR(16 + RAND() * (255 - 16))) || HEX(FLOOR(16 + RAND() * (255 - 16))) ) AS BG_COLOR , A.DVCLAS_NO FROM CALENDAR_INFO A LEFT JOIN COLORS B ON A.ROWNUM = B.ROWNUM

/* SQL ID : SchDAO.listSchedule 설 명 : 일정 조회 */
WITH M2 AS ( /* 학사일정*/ SELECT SYSJOB_SCHDL_TYCD AS CALENDAR_ID , ACAD_SCH_SN AS SCHEDULE_ID , '[' || (CASE UNIV_CD WHEN 'A' THEN '공통' WHEN 'C' THEN '대학' WHEN 'G' THEN '대학원' ELSE '' END) || ']' AS UNIV_CD , CALENDAR_REF_CD AS SCHEDULE_GUBUN , '[' || (CASE WHEN SYSJOB_SCHDL_TYCD = 'course' THEN '과목' ELSE '개인' END) || ']' AS PREFIX , ACAD_SCH_NM AS TTL , SCH_CNTS AS CONTENT , SYSJOB_SCHDL_SYMD AS SYMD , SYSJOB_SCHDL_EYMD AS EYMD FROM TB_HOME_ACAD_SCH WHERE ORG_ID = #{orgId} AND USEYN = 'Y'
AND ( SYSJOB_SCHDL_TYCD = 'personal'
OR CALENDAR_REF_CD IN (SELECT AA.SBJCT_ID FROM TB_LMS_TERM_CRE_CRS_RLTN AS AA JOIN TB_LMS_SBJCT AS BB ON AA.SBJCT_ID = BB.SBJCT_ID AND BB.DELYN = 'N' WHERE AA.CRS_SMSTR_ID = #{termCd} AND BB.UNIV_CD = #{uniCd})
OR CALENDAR_REF_CD IN (SELECT SBJCT_ID FROM TB_LMS_TERM_CRE_CRS_RLTN WHERE CRS_SMSTR_ID = #{termCd})
)
) , SCHEDULE_INFO AS ( SELECT CASE WHEN M2.CALENDAR_ID IN ('course', 'personal', 'schedule') THEN 'ALL' WHEN NVL((SELECT 'Y' FROM TB_LMS_ATNDLC_SBJCT WHERE USER_ID = #{userId} AND ROWNUM = 1), 'N') = 'Y' THEN 'STUDENT' ELSE 'PROFESSOR' END AS USER_TYPES , #{userId} AS USER_ID , M2.CALENDAR_ID , M2.SCHEDULE_ID , M2.UNIV_CD , M2.SCHEDULE_GUBUN , M2.PREFIX , M2.TTL , M2.CONTENT , M2.SYMD , M2.EYMD , CASE WHEN M2.CALENDAR_ID IN ('course', 'personal', 'schedule') THEN '0' ELSE CASE (SELECT SBJCT_TYCD FROM CRS WHERE CRS_ID = (SELECT CRS_ID FROM TB_LMS_SBJCT WHERE SBJCT_ID = M2.CALENDAR_ID)) WHEN 'UN I' THEN '1' WHEN 'CO' THEN '2' ELSE '3' END END AS ODR , CASE M2.CALENDAR_ID WHEN 'course' THEN '과목일정' WHEN 'personal' THEN '개인일정' WHEN 'schedule' THEN '업무일정' ELSE (SELECT SBJCTNM FROM TB_LMS_SBJCT WHERE SBJCT_ID = M2.CALENDAR_ID) END AS NAME , CASE WHEN M2.CALENDAR_ID IN ('course', 'personal', 'schedule') THEN '' ELSE (SELECT DVCLAS_NO FROM TB_LMS_SBJCT WHERE SBJCT_ID = M2.CALENDAR_ID) END AS DVCLAS_NO FROM M2 WHERE ( M2.CALENDAR_ID IN ('course', 'personal', 'schedule')
OR M2.CALENDAR_ID IN (SELECT AA.SBJCT_ID FROM TB_LMS_ATNDLC_SBJCT AS AA JOIN TB_LMS_SBJCT AS BB ON AA.SBJCT_ID = BB.SBJCT_ID AND BB.DELYN = 'N' WHERE AA.USER_ID = #{userId} AND AA.ATNDLC_STSCD = 'S' AND BB.UNIV_CD = #{uniCd}) OR M2.CALENDAR_ID IN (SELECT AA.SBJCT_ID FROM SBJCT_PROF AS AA JOIN TB_LMS_SBJCT AS BB ON AA.SBJCT_ID = BB.SBJCT_ID AND BB.DELYN = 'N' WHERE AA.USER_ID = #{userId} AND BB.UNIV_CD = #{uniCd})
OR M2.CALENDAR_ID IN (SELECT SBJCT_ID FROM TB_LMS_ATNDLC_SBJCT WHERE USER_ID = #{userId} AND ATNDLC_STSCD = 'S') OR M2.CALENDAR_ID IN (SELECT SBJCT_ID FROM SBJCT_PROF WHERE USER_ID = #{userId})
) ) SELECT CALENDAR_ID , SCHEDULE_ID , UNIV_CD , SCHEDULE_GUBUN , PREFIX , TTL , CONTENT , SYMD , EYMD , TO_CHAR(SYMD, 'YYYY-MM-DD"T"HH24:MI:SS') || '+09:00' AS START_FMT , TO_CHAR(EYMD, 'YYYY-MM-DD"T"HH24:MI:SS') || '+09:00' AS END_FMT , CASE WHEN CALENDAR_ID = 'course' THEN NAME || ' (' || (SELECT SBJCTNM || ' [' || DVCLAS_NO || '반]' FROM TB_LMS_SBJCT WHERE SBJCT_ID = SCHEDULE_GUBUN) || ')' ELSE NAME END AS NAME , CASE WHEN CALENDAR_ID = 'course' THEN (SELECT SBJCTNM || ' ' || DVCLAS_NO || '반' FROM TB_LMS_SBJCT WHERE SBJCT_ID = SCHEDULE_GUBUN) ELSE DVCLAS_NO END AS DVCLAS_NO FROM SCHEDULE_INFO WHERE ( USER_TYPES = 'ALL'
USER_TYPES LIKE '%' || #{item} || '%'
) AND ((USER_ID = #{userId} AND CALENDAR_ID != 'personal') OR CALENDAR_ID = 'schedule' OR (CALENDAR_ID = 'personal' AND SCHEDULE_GUBUN = #{userId}) OR (CALENDAR_ID = 'course' AND SCHEDULE_GUBUN IN (SELECT A.SBJCT_ID FROM TB_LMS_SBJCT A
JOIN TB_LMS_ATNDLC_SBJCT B ON A.SBJCT_ID = B.SBJCT_ID AND B.USER_ID = #{userId} AND B.ATNDLC_STSCD = 'S'
JOIN SBJCT_PROF B ON A.SBJCT_ID = B.SBJCT_ID AND B.USER_ID = #{userId} )) )
AND SUBSTR(SYMD,1,8) BETWEEN #{startDt} AND #{endDt}
AND ( SUBSTR(SYMD,1,8) BETWEEN #{startDt} AND #{endDt} OR SUBSTR(EYMD,1,8) BETWEEN #{startDt} AND #{endDt} OR (SUBSTR(SYMD,1,8) <= #{startDt} AND SUBSTR(EYMD,1,8) >= #{startDt}) OR CALENDAR_ID = 'schedule' )
AND CALENDAR_ID NOT IN ('personal', 'schedule')
AND CALENDAR_ID = 'personal'
AND CALENDAR_ID = 'schedule'
AND SCHEDULE_ID = #{scheduleId}
AND CALENDAR_ID NOT IN ('schedule', 'personal', 'course') AND (SUBSTR(SYMD,1,8) BETWEEN #{startDt} AND #{endDt} OR SUBSTR(EYMD,1,8) BETWEEN #{startDt} AND #{endDt} OR (SUBSTR(SYMD,1,8) <= #{startDt} AND SUBSTR(EYMD,1,8) >= #{startDt}) )
ORDER BY SYMD, EYMD
